actions.script:
const L = (text) => ec.l10n.localize(text)
newCode = ec.web.sessionAttributes.remove('newEdgePairingCode') || null
newCodeExpire = ec.web.sessionAttributes.remove('newEdgePairingExpire') || ''
linkKey = {linkFingerprint}
clientList = []
cursorList = []
nodeOptions = []
memberList = []
takeoverList = []
clientsError = ''
memoryError = ''
if (!isEdge) return
// a probe (Practices-App-Dev §4): a failure is shown on the page rather than failing it
let out = {}
let queueOut = {}
let membersOut = {}
let balancingOut = {}
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeClients').call() || {}
    if (!ec.message.hasError()) queueOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#QueueStatus').call() || {}
    if (ec.message.hasError()) clientsError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (clientsError) return
// what is kept in memory, in a probe of its own: a failure there leaves the rows shown
const probe = (name) => {
    ec.message.pushErrors()
    try {
        const answer = ec.service.sync().name('org.moqui.edge.EdgeServices.' + name).call() || {}
        if (!ec.message.hasError()) return answer
        memoryError = ec.message.getErrorsString()
        return {}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
membersOut = probe('get#EdgeMembers')
if (!memoryError) balancingOut = probe('get#EdgeBalancing')
// each node's queue: the items waiting for it (all kinds) and the failed ones, and the oldest waiting
const queues = {}
for (const kind of Array.from(queueOut.kindList || [])) {
    if (kind.directionEnumId !== 'EqdToLocal') continue
    const queue = queues[kind.pairedNodeId] ||
        (queues[kind.pairedNodeId] = {pending: 0, failed: 0, oldest: null})
    queue.pending += Number(kind.pending || 0)
    queue.failed += Number(kind.failed || 0)
    if (kind.oldestAgeSeconds != null) queue.oldest = Math.max(queue.oldest ?? 0, Number(kind.oldestAgeSeconds))
}
const age = (seconds) => seconds == null ? '' : seconds < 120 ? seconds + ' s' : seconds < 7200
    ? Math.round(seconds / 60) + ' min' : Math.round(seconds / 3600) + ' h'
cursorList = Array.from(queueOut.cursorList || []).map((cursor) => ({
    nodeId: cursor.pairedNodeId, setName: cursor.setName,
    epochText: cursor.epoch ? String(cursor.epoch).slice(0, 8) : '', seqText: String(cursor.sequenceNum ?? 0),
    valuesText: String(cursor.values ?? 0),
    appliedText: cursor.appliedDate ? ec.l10n.format(cursor.appliedDate, '') : '',
    snapshotText: cursor.snapshotDate ? ec.l10n.format(cursor.snapshotDate, '') : L('Not yet')}))
clientList = Array.from(out.clientList || []).map((client) => {
    const revoked = client.statusId === 'EdgeClientRevoked'
    const [stateLabel, stateColor] = revoked ? [L('Revoked'), 'negative']
        : client.linked && client.down ? [L('Linked'), 'positive']
        : client.linked ? [L('Connecting'), 'info'] : [L('Offline'), 'grey']
    const queue = queues[client.pairedNodeId]
    let queueText = L('Empty')
    if (queue) {
        queueText = queue.pending + ' ' + L('waiting')
        if (queue.oldest != null) queueText += ' (' + L('oldest') + ' ' + age(queue.oldest) + ')'
        if (queue.failed) queueText += ', ' + queue.failed + ' ' + L('failed')
    }
    return {pairedNodeId: client.pairedNodeId, stateLabel, stateColor, revoked, linked: !!client.linked && !!client.down,
        membersText: String(client.membersLinked ?? 0),
        newNodeText: client.holdNewMember ? L('Held for approval') + (client.approvedMemberId ? ' (' + client.approvedMemberId + ' ' + L('approved') + ')' : '')
            : L('Admitted, with a notice'),
        holdNewMember: !!client.holdNewMember,
        generationText: client.generation ? String(client.generation) : '',
        lastConnectText: client.lastConnectDate ? ec.l10n.format(client.lastConnectDate, '') : L('Never'),
        remoteAddress: client.remoteAddress || '',
        versionText: (client.binaryVersion || '') + (client.linkVersion ? ' · ' + L('link') + ' ' + client.linkVersion : ''),
        keyShort: client.keyFingerprint ? String(client.keyFingerprint).slice(0, 16) + '…' : '',
        queueText,
        capText: client.queueMaxMegabytes ? client.queueMaxMegabytes + ' MB' : L('The conf\'s')}
})
nodeOptions = clientList.filter((client) => !client.revoked).map((client) => ({nodeId: client.pairedNodeId}))
// the takeovers noted on each pairing (plans/Edge-Node2.md §4.5): the node displaced stays refused until cleared
takeoverList = Array.from(out.clientList || []).filter((client) => client.takeoverDate).map((client) => ({
    pairedNodeId: client.pairedNodeId, toId: client.takeoverToId || '',
    fromText: client.takeoverFromId || '',
    dateText: ec.l10n.format(client.takeoverDate, ''),
    displaced: !!client.takeoverFromId,
    refusedText: client.takeoverFromId ? L('Refused until you let it link again') : L('May link again')}))
// each pairing's members (plans/Edge-Node2.md §4.4): the links, the member list they send, the refusals
const conditions = {ok: [L('Linked'), 'positive'], notLinked: [L('Not linked'), 'negative'],
    staleHeartbeat: [L('Stale heartbeat'), 'warning'], otherVersion: [L('Other version'), 'warning'],
    stopped: [L('Stopped'), 'grey'], held: [L('Held for approval'), 'warning'], refused: [L('Refused'), 'negative']}
const states = {live: L('Live'), starting: L('Starting'), draining: L('Draining'), stopping: L('Stopping')}
// the work in flight on each member, as balancing counts it
const inFlight = {}
for (const row of Array.from(balancingOut.memberList || [])) inFlight[row.pairedNodeId + ' ' + row.instanceId] = row
// a pairing's live members: draining the last one takes its names offline
const liveCount = {}
for (const member of Array.from(membersOut.memberList || [])) {
    if (member.linked && member.state === 'live') liveCount[member.pairedNodeId] = (liveCount[member.pairedNodeId] || 0) + 1
}
memberList = Array.from(membersOut.memberList || []).map((member) => {
    const work = inFlight[member.pairedNodeId + ' ' + member.instanceId]
    const [conditionLabel, conditionColor] = conditions[member.condition] || [member.condition || '', 'grey']
    const linked = !!member.linked
    return {pairedNodeId: member.pairedNodeId, instanceId: member.instanceId, conditionLabel, conditionColor,
        stateText: linked ? states[member.state] || member.state || '' : '',
        versionText: member.version || member.binaryVersion || '',
        remoteAddress: member.remoteAddress || '',
        heartbeatText: member.inCluster ? age(Math.round(Number(member.heartbeatAgeMs ?? 0) / 1000))
            + (member.liveInCluster ? '' : ', ' + L('stale')) : linked ? L('Not in its cluster\'s list') : '',
        lastSeenText: member.lastSeenDate ? ec.l10n.format(member.lastSeenDate, '') : '',
        inFlightText: work ? String(work.inFlight ?? 0) + (work.setAside ? ', ' + L('set aside') : '') : '',
        message: member.message || '',
        canPing: linked && !!member.down && !notStarted,
        canDrain: linked && !!member.down && !notStarted && member.state !== 'draining',
        canResume: linked && !!member.down && !notStarted && member.state === 'draining',
        lastLive: linked && member.state === 'live' && (liveCount[member.pairedNodeId] || 0) <= 1,
        held: member.condition === 'held',
        canForget: !linked}
})
